window.__denzingerWorks["dz_073"] = {"id":"dz_073","a":"Denzinger (1819-1883) — 11e éd., Bannwart S.J., 1911","t":"Conc. LATERANENSE III 1179","u":"https://archive.org/details/enchiridionsymbo01denz","c":[{"t":"Conc. LATERANENSE III 1179","s":[{"t":"Conc. LATERANENSE III 1179","p":["Oecumenicum XI (contra Waldenses et Albigenses).","ahquid dederit, ad sacros ordines non ascendat. Is autem qui acceperit, officii sui privatione mulctetur^.","Baptismus. — Simonia. — Haeretici evitandi. — Sacramenta. 175","Cap. 27. Sicut ait beatus LEO, hcet ecclesiastica401 disciplina, sacerdotah contenta iudicio, cruentas non ^^^^^ efficiat ultiones : cathohcorum tamen principum constitutionibus adiuvatur, ut saepe quaerant homines salutare remedium, dum corporale super se metuunt evenire supplicium. Eapropter, quia in Gasconia, Albegesio et partibus Tolosanis et ahis locis ita haereticorum , quos ahi Catharos, alii Patarenos, ahi Pubhcanos, ahi ahis nominibus vocant, invaluit damnata perversitas, ut iam non in occulto, sicut ahqui, nequitiam suam exerceant, sed suum errorem pubhce manifestent et ad suum consensum simphces attrahant et infirmos: eos et defensores et receptatores eorum anathemati decernimus subiacere, et sub anathemate prohibemus, ne quis eos in domibus vel in terra sua tenere vel fovere vel negotiationem cum eis exercere praesumat 2."]}]}]};
